    if(!t) return {ok:true,name:last,how:'gone'};
    last=t.name; const idx=t.index;
    const r=await bot.attack(t);
    if(!r.success){ await sdk.waitForTicks(2); continue; }
    const hp0=await sdk.waitForCondition(s=>{const n=s.nearbyNpcs.find(x=>x.index===idx);return !n||n.hp===0;},12000).then(()=>true).catch(()=>false);
    if(hp0){const gone=await sdk.waitForCondition(s=>!s.nearbyNpcs.some(n=>n.index===idx),8000).then(()=>true).catch(()=>false); if(gone) return {ok:true,name:last,how:'killed'};}
  }
  return {ok:false,name:last,reason:'timeout'};
}
